format_code:
chip esp32

hardware {
    pin buzzer: PWM = 25
}

enum AlertLevel { normal, warning, critical }

task monitor {
    every 5s {
        var level: AlertLevel = AlertLevel.normal
        if level == AlertLevel.critical {
            buzzer.beep_alarm()
        }
    }
}

